package com.bn.aliagent.evaluation.dataset;
import static org.junit.jupiter.api.Assertions.*;
import com.bn.aliagent.evaluation.candidate.*;
import com.bn.aliagent.evaluation.anonymization.*;
import java.time.Instant; import java.util.*; import org.junit.jupiter.api.Test;
class EvaluationDatasetServiceTest {
 @Test void publishesStableImmutableSnapshotFromAcceptedCandidates(){var candidates=new CandidateRepository.InMemory();var accepted=EvaluationCandidate.pending(UUID.randomUUID(),"test-p8-a-tenant","{\"input\":\"test\"}","d",Instant.now());candidates.save(accepted);var review=new CandidateReviewService(candidates);review.review(new CandidateReviewCommand(accepted.id(),"test-p8-a-tenant","r",ReviewAction.ACCEPT,Map.of("intent","x"),Set.of("test"),"ok"));var service=new EvaluationDatasetService(candidates,new PublicDatasetAnonymizer(new DeterministicAnonymizer("public")));var draft=service.createDraft("test-p8-a-tenant","d");service.addCandidate("test-p8-a-tenant",draft.id(),accepted.id());var published=service.publish("test-p8-a-tenant",draft.id(),false,null);assertEquals(1,published.samples().size());assertEquals(published.digest(),service.requirePublished("test-p8-a-tenant",published.id()).digest());assertThrows(IllegalStateException.class,()->service.addCandidate("test-p8-a-tenant",draft.id(),accepted.id()));}
 @Test void publicPublicationNeedsAuthorization(){var candidates=new CandidateRepository.InMemory();var accepted=EvaluationCandidate.pending(UUID.randomUUID(),"test-p8-a-tenant","{\"userId\":\"u\"}","d",Instant.now());candidates.save(accepted);var review=new CandidateReviewService(candidates);review.review(new CandidateReviewCommand(accepted.id(),"test-p8-a-tenant","r",ReviewAction.ACCEPT,Map.of("intent","x"),Set.of("test"),"ok"));var service=new EvaluationDatasetService(candidates,new PublicDatasetAnonymizer(new DeterministicAnonymizer("public")));var draft=service.createDraft("test-p8-a-tenant","d");service.addCandidate("test-p8-a-tenant",draft.id(),accepted.id());assertThrows(SecurityException.class,()->service.publish("test-p8-a-tenant",draft.id(),true,DatasetShareAuthorization.inactive()));assertTrue(service.publish("test-p8-a-tenant",draft.id(),true,DatasetShareAuthorization.active("admin",Instant.now())).publiclyShared());}
}
